const T = 2;
const RANGES = {
    s1: [0, 100],
    s2: [0, 100],
    s3: [0, 1]
};

const text = String(msg.payload ?? "").replace(/^\uFEFF/, "");
const sql = [];

text.split(/\r?\n/).forEach(raw => {
    const line = raw.trim();
    if (!line) return;

    const parts = line.split(/\s+/);
    const kind = parts[0];
    const f = {};

    parts.slice(1).forEach(p => {
        const i = p.indexOf("=");
        if (i > 0) {
            f[p.slice(0, i)] = p.slice(i + 1);
        }
    });

    const n = Number.parseInt(f.n, 10);
    if (!Number.isInteger(n) || n < 1) return;

    const t = n * T;

    if (kind === "DATA") {
        ["s1", "s2", "s3"].forEach(s => {
            const v = Number(f[s]);

            if (f[s] === undefined || !Number.isFinite(v)) {
                sql.push(
                    `INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'FAULT','датчик ${s}: некорректное значение');`
                );
                return;
            }

            sql.push(
                `INSERT INTO readings(n,t_s,sensor,value) VALUES(${n},${t},'${s}',${v});`
            );

            if (v < RANGES[s][0] || v > RANGES[s][1]) {
                sql.push(
                    `INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'FAULT','датчик ${s} вне диапазона');`
                );
            }
        });
    } else if (kind === "EVENT") {
        const type = String(f.type || "").replace(/'/g, "''");
        if (["THRESHOLD", "NORMAL"].includes(type)) {
            sql.push(
                `INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'${type}','');`
            );
        }
    }
});

msg.payload =
    "BEGIN;\n" +
    "DELETE FROM readings;\n" +
    "DELETE FROM events;\n" +
    "DELETE FROM sqlite_sequence WHERE name IN ('readings','events');\n" +
    sql.join("\n") +
    "\nCOMMIT;\n";

return msg;
